gcE(){return"\u03bb\u03b9\u03b3\u03cc\u03c4\u03b5\u03c1\u03b1"},
gdT(){return"\u03a3\u03c5\u03bc\u03bc\u03b5\u03c4\u03ad\u03c7\u03bf\u03bd\u03c4\u03b5\u03c2"},
ge_(){return"\u0394\u03b5\u03af\u03c4\u03b5"},
