gdU(){return"\u0442\u043e\u043c\u0443 \u043d\u0430\u0437\u0430\u0434"},
ge6(){return"\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c\u0441\u044f"},
