ge2(){return"\u041f\u0440\u0438\u0454\u0434\u043d\u0443\u0439\u0442\u0435\u0441\u044c \u0434\u043e \u0432\u0456\u0434\u0435\u043e\u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0456\u0439, \u044f\u043a\u0449\u043e \u0432\u0438 \u0432\u0436\u0435 \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u043e\u0432\u0430\u043d\u0456."},
gcP(){return"\u041e\u0442\u0440\u0438\u043c\u0430\u0439\u0442\u0435 \u043d\u043e\u0432\u0443 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0443"},
gdk(){return"\u0417\u043d\u0430\u0439\u043e\u043c\u0442\u0435\u0441\u044c \u0437 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u043e\u044e"},
gdl(){return"\u0417\u0430\u0440\u043e\u0431\u043b\u044f\u0439\u0442\u0435 \u0433\u0440\u043e\u0448\u0456"},
gdm(){return"\u041f\u0440\u0438\u0454\u0434\u043d\u0443\u0439\u0442\u0435\u0441\u044c \u0442\u0443\u0442!"},
gcW(){return"\u0414\u0438\u043d\u0430\u043c\u0456\u0447\u043d\u0456 \u043a\u0443\u0440\u0441\u0438 \u0437 \u0456\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u0438\u043c\u0438 \u0442\u0435\u0441\u0442\u0430\u043c\u0438"},
gcX(){return"\u0414\u043e\u0434\u0430\u0439\u0442\u0435 \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0438 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0456 \u0406\u0406 \u0434\u043e \u0432\u0430\u0448\u0438\u0445 \u043a\u0443\u0440\u0441\u0456\u0432"},
gcY(){return"\u041c\u043e\u043d\u0435\u0442\u0438\u0437\u0443\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0434\u043e\u0441\u0432\u0456\u0434 \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e \u043a\u0456\u043b\u044c\u043a\u043e\u0445 \u0434\u0436\u0435\u0440\u0435\u043b \u0434\u043e\u0445\u043e\u0434\u0443"},
gcZ(){return"\u041c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u0456\u0439\u043d\u0456 \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0438 \u0434\u043b\u044f \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u043f\u043b\u0438\u0432\u0443"},
gcS(){return"\u0421\u0442\u0432\u043e\u0440\u044e\u0439\u0442\u0435 \u0456\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u0456 \u043a\u0443\u0440\u0441\u0438 \u0437 \u0442\u0435\u0441\u0442\u0430\u043c\u0438, \u044f\u043a\u0456 \u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u0437\u0430\u0432\u0434\u0430\u043d\u043d\u044f \u0432\u0430\u0448\u0438\u043c \u043f\u0456\u0434\u043f\u0438\u0441\u043d\u0438\u043a\u0430\u043c. \u0414\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043f\u0438\u0442\u0430\u043d\u043d\u044f, \u0432\u0456\u0434\u0435\u043e \u0437 YouTube, \u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u043d\u044f, \u0430\u0443\u0434\u0456\u043e \u0442\u0430 \u043d\u0430\u0432\u0456\u0442\u044c \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u043d\u0456 \u0440\u0456\u0432\u043d\u044f\u043d\u043d\u044f \u0434\u043b\u044f \u0437\u0431\u0430\u0433\u0430\u0447\u0435\u043d\u043d\u044f \u0434\u043e\u0441\u0432\u0456\u0434\u0443. \u0417\u0430\u043b\u0443\u0447\u0430\u0439\u0442\u0435 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0456\u044e \u0434\u0438\u043d\u0430\u043c\u0456\u0447\u043d\u0438\u043c \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u043e\u043c \u0456 \u0432\u0438\u0432\u043e\u0434\u044c\u0442\u0435 \u0432\u0430\u0448 \u043a\u0443\u0440\u0441 \u043d\u0430 \u043d\u043e\u0432\u0438\u0439 \u0440\u0456\u0432\u0435\u043d\u044c."},
gcT(){return"\u041f\u043e\u043a\u0440\u0430\u0449\u0443\u0439\u0442\u0435 \u0441\u0432\u043e\u0457 \u043a\u0443\u0440\u0441\u0438 \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0456\u0432, \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u0438\u0445 \u0437\u0430 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u043e\u044e \u0406\u0406. \u0421\u0442\u0432\u043e\u0440\u044e\u0439\u0442\u0435 \u0430\u0443\u0434\u0456\u043e \u0432\u0438\u0441\u043e\u043a\u043e\u0457 \u044f\u043a\u043e\u0441\u0442\u0456 \u043d\u0430 \u043a\u0456\u043b\u044c\u043a\u043e\u0445 \u043c\u043e\u0432\u0430\u0445 \u0456 \u0433\u043e\u043b\u043e\u0441\u0430\u0445, \u0437\u0430\u043e\u0449\u0430\u0434\u0436\u0443\u044e\u0447\u0438 \u0447\u0430\u0441 \u0456 \u043e\u0445\u043e\u043f\u043b\u044e\u044e\u0447\u0438 \u0441\u0432\u0456\u0442\u043e\u0432\u0443 \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0456\u044e \u2014 \u0431\u0435\u0437 \u043f\u043e\u0442\u0440\u0435\u0431\u0438 \u0443 \u0441\u0442\u0443\u0434\u0456\u0457 \u0437\u0432\u0443\u043a\u043e\u0437\u0430\u043f\u0438\u0441\u0443!"},
gcU(){return"\u0417\u0431\u0456\u043b\u044c\u0448\u0443\u0439\u0442\u0435 \u0441\u0432\u043e\u0457 \u0434\u043e\u0445\u043e\u0434\u0438 \u0447\u0435\u0440\u0435\u0437 \u043f\u0456\u0434\u043f\u0438\u0441\u043a\u0438 \u043d\u0430 \u043a\u043e\u043d\u0442\u0435\u043d\u0442 \u043f\u043e\u0447\u0438\u043d\u0430\u044e\u0447\u0438 \u0437 5,99 USD. \u0412\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0439\u0442\u0435 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u0456 \u0432\u0456\u0434\u0435\u043e \u0442\u0430 \u043f\u0440\u044f\u043c\u0456 \u0435\u0444\u0456\u0440\u0438 \u0434\u043b\u044f \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u0457 \u0437 \u0432\u0430\u0448\u043e\u044e \u0430\u0443\u0434\u0438\u0442\u043e\u0440\u0456\u0454\u044e. \u0422\u0430\u043a\u043e\u0436 \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u043e\u0442\u0440\u0438\u043c\u0443\u0432\u0430\u0442\u0438 \u0447\u0430\u0457, \u044f\u043a\u0456 \u0432\u0430\u0440\u0456\u044e\u044e\u0442\u044c\u0441\u044f \u0432\u0456\u0434 3,99 \u0434\u043e 14,99 USD \u0437\u0430 \u043a\u0443\u0440\u0441."},
gcV(){return"\u0412\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0439\u0442\u0435 \u043d\u0430\u0448\u0456 \u043f\u043e\u0442\u0443\u0436\u043d\u0456 \u043c\u0443\u043b\u044c\u0442\u0438\u043c\u0435\u0434\u0456\u0439\u043d\u0456 \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0438 \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043a\u0443\u0440\u0441\u0456\u0432, \u0449\u043e \u0432\u0438\u0434\u0456\u043b\u044f\u044e\u0442\u044c\u0441\u044f. \u0427\u0438 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0454\u0442\u0435 \u0432\u0438 \u0432\u0456\u0434\u0435\u043e, \u0456\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u0456 \u0442\u0435\u0441\u0442\u0438 \u0447\u0438 \u0432\u0456\u0434\u0435\u043e\u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0456\u0457 \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u0447\u0430\u0441\u0456, \u043d\u0430\u0448\u0430 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u0456\u0434\u0435\u0430\u043b\u044c\u043d\u0456 \u0444\u0443\u043d\u043a\u0446\u0456\u0457 \u0434\u043b\u044f \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043f\u0440\u0438\u0432\u0430\u0431\u043b\u0438\u0432\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u0443, \u044f\u043a\u0438\u0439 \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442\u044c \u0434\u043e\u0445\u0456\u0434."},
gei(){return"\u042f\u043a\u0449\u043e \u0443 \u0432\u0430\u0441 \u0454 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043f\u0440\u043e \u043d\u0430\u0448\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0456\u044e, \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u043d\u0430\u043f\u0438\u0441\u0430\u0442\u0438 \u043d\u0430\u043c \u0447\u0435\u0440\u0435\u0437 \u0444\u043e\u0440\u043c\u0443 \u043d\u0438\u0436\u0447\u0435"},
gdW(){return"\u041d\u0430\u043f\u0438\u0448\u0456\u0442\u044c \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0442\u0443\u0442"},
gdE(a){return"\u0412\u0456\u0434\u043f\u0440\u0430\u0432\u0438\u0442\u0438"},
gdF(){return"\u0412\u0456\u0434\u043f\u0440\u0430\u0432\u043a\u0430"},
