gdq(){return"\u041d\u0430\u043f\u0438\u0448\u0456\u0442\u044c \u0435\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u0443 \u043f\u043e\u0448\u0442\u0443 \u0442\u0443\u0442"},
gdK(){return"\u0412\u0432\u0435\u0434\u0456\u0442\u044c \u0456\u043c'\u044f"},
