gdJ(){return"\u0412\u0432\u0435\u0434\u0456\u0442\u044c \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f"},
gd6(){return"\u0421\u043b\u0456\u0434\u043a\u0443\u0439\u0442\u0435 \u0437\u0430 \u043d\u0430\u043c\u0438"},
geu(){return"\u041f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e"},
gbj(a){return"\u041f\u043e\u043c\u0438\u043b\u043a\u0430. \u0411\u0443\u0434\u044c \u043b\u0430\u0441\u043a\u0430, \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437"},
gdM(){return"\u0417\u0430\u043f\u043e\u0432\u043d\u0456\u0442\u044c \u0443\u0441\u0456 \u043f\u043e\u043b\u044f \u043f\u0435\u0440\u0435\u0434 \u0432\u0456\u0434\u043f\u0440\u0430\u0432\u043a\u043e\u044e"},
gdH(){return"\u042f\u043a\u0449\u043e \u0432\u0438 \u0441\u043f\u0456\u0432\u0440\u043e\u0431\u0456\u0442\u043d\u0438\u043a edhomy, \u0443\u0432\u0456\u0439\u0434\u0456\u0442\u044c \u0434\u043b\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u0443"},
gev(){return"\u041a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u0442\u0430 \u043f\u0430\u0440\u043e\u043b\u044c"},
gey(){return"\u041d\u0430\u043f\u0438\u0448\u0456\u0442\u044c \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0442\u0443\u0442"},
gdY(){return"\u041d\u0430\u043f\u0438\u0448\u0456\u0442\u044c \u043f\u0430\u0440\u043e\u043b\u044c \u0442\u0443\u0442"},
gdu(a){return"\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438"},
geq(){return"\u041f\u0430\u0440\u043e\u043b\u044c \u0430\u0431\u043e \u0456\u043c'\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u043d\u0435 \u0454 \u0434\u0456\u0439\u0441\u043d\u0438\u043c. \u0411\u0443\u0434\u044c \u043b\u0430\u0441\u043a\u0430, \u0437\u0432'\u044f\u0436\u0456\u0442\u044c\u0441\u044f \u0437 \u0432\u0430\u0448\u0438\u043c \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u043e\u043c"},
ged(){return"\u0411\u0443\u0434\u044c \u043b\u0430\u0441\u043a\u0430, \u0432\u0432\u0435\u0434\u0456\u0442\u044c \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u0435 \u0456\u043c'\u044f \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430 \u0442\u0430 \u043f\u0430\u0440\u043e\u043b\u044c"},
gcI(){return"\u0412\u0438\u0439\u0442\u0438"},
gdG(){return"\u041f\u0440\u043e\u0433\u0440\u0430\u043c\u0430"},
gdf(){return"\u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f \u0437\u0430 \u0446\u0438\u043c \u0437\u0430\u043f\u0438\u0442\u043e\u043c \u043d\u0435 \u0437\u043d\u0430\u0439\u0434\u0435\u043d\u0430"},
gdD(){return"\u0421\u043e\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0437\u0430 \u043d\u0430\u0437\u0432\u043e\u044e"},
gdC(){return"\u0421\u043e\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0437\u0430 \u043e\u043f\u0438\u0441\u043e\u043c"},
geo(){return"\u0421\u043e\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0437\u0430 \u0456\u043c\u0435\u043d\u0435\u043c"},
gep(){return"\u0421\u043e\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0437\u0430 \u043f\u043e\u0441\u0430\u0434\u043e\u044e"},
gdB(){return"\u041d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0437\u043d\u0430\u0439\u0434\u0435\u043d\u043e \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u043e\u0437\u0434\u0456\u043b\u0456"},
gcQ(a){return"\u041f\u043e\u0448\u0443\u043a"},
gdU(){return"\u0442\u043e\u043c\u0443 \u043d\u0430\u0437\u0430\u0434"},
ge6(){return"\u041f\u0456\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u0438"},
